import React, {useState,useEffect} from 'react';
import {loadUserData,saveUserData} from './storage';
import {View, Text, TextInput, ScrollView, Pressable, Image, SafeAreaView, StatusBar, StyleSheet, Dimensions, KeyboardAvoidingView, Platform, Alert, Linking} from 'react-native';
