const imagesByKey={pasta:require('./pasta.jpg'),travel:require('./travel.jpg'),room:require('./room.jpg'),cake:require('./cake.jpg'),coffee:require('./coffee.jpg'),film:require('./film.jpg'),mountain:require('./mountain.jpg'),food:require('./food.jpg'),city:require('./city.jpg'),salad:require('./salad.jpg')};
