const communityScreen=()=> <View style={{flex:1}}><View style={[s.row,{paddingHorizontal:20,paddingTop:25,justifyContent:'space-between'}]}><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:23}}>{['Home','Friends','Nearby','Events'].map(t=><Pressable key={t} onPress={()=>setCommunity(t)} style={[s.profileTab,community===t&&s.profileTabActive]}><Text style={{fontSize:17,fontWeight:'700',color:community===t?'#fff':'#777'}}>{t}</Text></Pressable>)}</ScrollView><Pressable onPress={()=>setScreen('search')}>{icon('search',25)}</Pressable></View>{community==='Friends'?<View style={[s.profileEmpty,{flex:1}]}>{icon('reader-outline',74,'#ddd')}<Title style={{fontSize:25,marginTop:25}}>No posts yet</Title><Small style={{fontSize:15,marginTop:9}}>Posts will appear here as people share</Small></View>:<ScrollView contentContainerStyle={{paddingHorizontal:22,paddingTop:34,paddingBottom:100}}><View style={[s.row,{marginBottom:22}]}><View style={[s.avatar,{width:42,height:42}]}>{txt('K',{fontWeight:'700'})}</View><View style={{flex:1}}>{txt('Keepsake picks',{fontWeight:'700'})}<Small>Saved a moment · Preview</Small></View>{icon('ellipsis-vertical',20,'#777')}</View><Title style={{fontSize:25}}>A little inspiration for today</Title><Text style={[s.text,{fontFamily:'serif',marginTop:8,marginBottom:19}]}>The good ideas we keep coming back to.</Text><Pic uri={PHOTO.mountain} style={{height:365,borderRadius:20}}/><Text style={{fontSize:22,color:'#fff',marginTop:15}}>★★★★☆</Text><Small style={{marginTop:10}}>Sample community post. No live social feed.</Small></ScrollView>}</View>;
