<View style={s.profileIdentity}><View style={{flex:1}}><Title style={{fontSize:28}}>{profileName}</Title><Text style={{color:'#ededed',fontSize:16,marginTop:3}}>{profileHandle} 🌿</Text></View><View style={s.avatar}>{txt('D',{fontSize:31,fontWeight:'700',color:'#e8eeff'})}</View></View>
